1	`include "define.v"
2	
3	module OooFetchAxiBridge (
4	  input clk,
5	  input rst,
6	  input mmu_flush_i,
7	
8	  input invalidate_valid_i,
9	  input [`XLEN-1:0] invalidate_addr_i,
10	
11	  input [1:0] priv_mode_i,
12	  input [`XLEN-1:0] satp_i,
13	  input svpbmt_en_i,
14	  input [`PMP_CFG_BUS_W-1:0] pmpcfg_i,
15	  input [`PMP_ADDR_BUS_W-1:0] pmpaddr_i,
16	
17	  input fetch_req_valid_i,
18	  output fetch_req_ready_o,
19	  input [`XLEN-1:0] fetch_req_pc_i,
20	  output fetch_rsp_valid_o,
21	  input fetch_rsp_ready_i,
22	  output [`INST_W-1:0] fetch_rsp_inst0_o,
23	  output [1:0] fetch_rsp_resp0_o,
24	  output [`INST_W-1:0] fetch_rsp_inst1_o,
25	  output [1:0] fetch_rsp_resp1_o,
26	
27	  output ifu_axi_arvalid_o,
28	  input ifu_axi_arready_i,
29	  output [`XLEN-1:0] ifu_axi_araddr_o,
30	  input ifu_axi_rvalid_i,
31	  output ifu_axi_rready_o,
32	  input [`XLEN-1:0] ifu_axi_rdata_i,
33	  input [1:0] ifu_axi_rresp_i,
34	
35	  // HW-managed A 更新写通道（Svadu，对齐 NEMU）：取指到 A=0 的可执行页时，
36	  // 不再 page fault，改经 S_AD_UPDATE 写回 PTE 置 A 位。取指只置 A（不置 D）。
37	  output ifu_axi_awvalid_o,
38	  input ifu_axi_awready_i,
39	  output [`XLEN-1:0] ifu_axi_awaddr_o,
40	  output ifu_axi_wvalid_o,
41	  input ifu_axi_wready_i,
42	  output [`XLEN-1:0] ifu_axi_wdata_o,
43	  output [`STRB_W-1:0] ifu_axi_wstrb_o,
44	  input ifu_axi_bvalid_i,
45	  output ifu_axi_bready_o,
46	  input [1:0] ifu_axi_bresp_i
47	);
48	
49	  localparam [3:0] S_IDLE = 4'd0;
50	  localparam [3:0] S_WALK_AR = 4'd1;
51	  localparam [3:0] S_WALK_R = 4'd2;
52	  localparam [3:0] S_AR0 = 4'd3;
53	  localparam [3:0] S_R0 = 4'd4;
54	  localparam [3:0] S_AR1 = 4'd5;
55	  localparam [3:0] S_R1 = 4'd6;
56	  localparam [3:0] S_RESP = 4'd7;
57	  localparam [3:0] S_AD_UPDATE = 4'd8;  // HW A 更新: 写回 leaf PTE 置 A 位, 再 re-walk 续原取指
58	  localparam [3:0] S_LOOKUP = 4'd9;     // 取指包 cache SRAM 同步读判决拍(fire 次拍, ready=0)
59	  localparam [`XLEN-1:0] PTE_A_BIT = {{(`XLEN-7){1'b0}}, 7'h40};  // bit 6 (Accessed)
60	  localparam [1:0] RESP_OK = 2'b00;
61	  localparam [1:0] RESP_ACCESS_FAULT = 2'b01;
62	  localparam [1:0] RESP_PAGE_FAULT = 2'b10;
63	  localparam ITLB_INDEX_W = 6;
64	
65	  reg [3:0] state_q;
66	  reg paging_q;
67	  reg [1:0] req_priv_q;
68	  reg [`XLEN-1:0] req_satp_q;
69	  reg req_svpbmt_en_q;
70	  reg walk_second_q;
71	  reg [1:0] walk_level_q;
72	  reg [43:0] walk_ppn_q;
73	  reg [`XLEN-1:0] pc_q;
74	  reg [`XLEN-1:0] paddr0_q;
75	  reg [`XLEN-1:0] paddr1_q;
76	  reg packet_cross_page_q;
77	  reg [2:0] packet_first_bytes_q;
78	  reg [`XLEN-1:0] first_beat_q;
79	  reg [`INST_W-1:0] inst0_q;
80	  reg [`INST_W-1:0] inst1_q;
81	  reg [1:0] resp0_q;
82	  reg [1:0] resp1_q;
83	  reg [`XLEN-1:0] debug_last_pte_addr_q;
84	  reg [`XLEN-1:0] debug_last_pte_q;
85	  reg [1:0] debug_last_pte_level_q;
86	  reg debug_last_pte_second_q;
87	  reg [`XLEN-1:0] ad_pte_q;   // HW A: 置 A 位后的 leaf PTE(供 S_AD_UPDATE 写通道)
88	  reg aw_done_q;              // S_AD_UPDATE 的 AW 已握手(吸收 awready/wready 偏斜)
89	  reg w_done_q;               // S_AD_UPDATE 的 W 已握手
90	
91	  function sv39_enabled;
92	    input [1:0] priv_mode;
93	    input [`XLEN-1:0] satp;
94	    begin
95	      sv39_enabled = (priv_mode != `PRIV_M) && (satp[63:60] == 4'h8);
96	    end
97	  endfunction
98	
99	  function canonical_sv39;
100	    input [`XLEN-1:0] vaddr;
101	    begin
102	      canonical_sv39 = (vaddr[63:39] == {25{vaddr[38]}});
103	    end
104	  endfunction
105	
106	  function [8:0] vpn_by_level;
107	    input [`XLEN-1:0] vaddr;
108	    input [1:0] level;
109	    begin
110	      case (level)
111	        2'd2: vpn_by_level = vaddr[38:30];
112	        2'd1: vpn_by_level = vaddr[29:21];
113	        default: vpn_by_level = vaddr[20:12];
114	      endcase
115	    end
116	  endfunction
117	
118	  function [`XLEN-1:0] pte_addr;
119	    input [43:0] ppn;
120	    input [`XLEN-1:0] vaddr;
121	    input [1:0] level;
122	    begin
123	      pte_addr = {8'b0, ppn, 12'b0} +
124	                 {{(`XLEN-12){1'b0}}, vpn_by_level(vaddr, level), 3'b000};
125	    end
126	  endfunction
127	
128	  function pte_invalid;
129	    input [`XLEN-1:0] pte;
130	    begin
131	      pte_invalid = !pte[0] || (!pte[1] && pte[2]);
132	    end
133	  endfunction
134	
135	  function pte_leaf;
136	    input [`XLEN-1:0] pte;
137	    begin
138	      pte_leaf = pte[1] || pte[3];
139	    end
140	  endfunction
141	
142	  function pte_reserved_fault;
143	    input [`XLEN-1:0] pte;
144	    input svpbmt_en;
145	    input [1:0] level;
146	    begin
147	      pte_reserved_fault =
148	          (pte_leaf(pte) ?
149	           (((pte & ((svpbmt_en ? `SV39_PTE_RESERVED_MASK_SVPBMT :
150	                                  `SV39_PTE_RESERVED_MASK) &
151	                                 ~`SV39_PTE_N)) != {`XLEN{1'b0}}) ||
152	            (((pte & `SV39_PTE_N) != {`XLEN{1'b0}}) &&
153	             ((level != 2'd0) || (pte[13:10] != 4'b1000)))) :
154	           (((pte & (svpbmt_en ? `SV39_PTE_RESERVED_MASK_SVPBMT :
155	                                  `SV39_PTE_RESERVED_MASK)) !=
156	             {`XLEN{1'b0}}) ||
157	            ((pte & `SV39_PTE_NONLEAF_RESERVED_MASK) != {`XLEN{1'b0}}) ||
158	            (svpbmt_en &&
159	             (pte[`SV39_PTE_PBMT_HI:`SV39_PTE_PBMT_LO] != 2'b00)))) ||
160	          (pte_leaf(pte) && svpbmt_en &&
161	           (pte[`SV39_PTE_PBMT_HI:`SV39_PTE_PBMT_LO] == 2'b11));
162	    end
163	  endfunction
164	
165	  function superpage_misaligned;
166	    input [`XLEN-1:0] pte;
167	    input [1:0] level;
168	    begin
169	      case (level)
170	        2'd2: superpage_misaligned = (|pte[27:10]);
171	        2'd1: superpage_misaligned = (|pte[18:10]);
172	        default: superpage_misaligned = 1'b0;
173	      endcase
174	    end
175	  endfunction
176	
177	  // HW-managed A（Svadu，对齐 NEMU）：A 缺失不再算权限 fault，改由 S_AD_UPDATE 写回置位。
178	  // 真权限（X、U/S）仍在此判。
179	  function exec_permission_fault;
180	    input [`XLEN-1:0] pte;
181	    input [1:0] priv_mode;
182	    begin
183	      exec_permission_fault =
184	          !pte[3] ||
185	          ((priv_mode == `PRIV_U) ? !pte[4] : pte[4]);
186	    end
187	  endfunction
188	
189	  // 取指到真权限全通过但 A=0 的 leaf → 触发 HW A 更新（写 PTE|A 后 re-walk），非 fault。
190	  function exec_ad_update_needed;
191	    input [`XLEN-1:0] pte;
192	    begin
193	      exec_ad_update_needed = !pte[6];
194	    end
195	  endfunction
196	
197	  function [`XLEN-1:0] leaf_paddr;
198	    input [`XLEN-1:0] pte;
199	    input [`XLEN-1:0] vaddr;
200	    input [1:0] level;
201	    begin
202	      // Svnapot 64KiB leaf: PTE.PPN[3:0] 是 NAPOT 编码(1000)，真实 PA
203	      // 低 4 个 PPN bit 必须来自 VA[15:12]，否则会写到 64KiB 窗口中间。
204	      leaf_paddr = {8'b0,
205	                    (level == 2'd2) ?
206	                    {pte[53:28], vaddr[29:21], vaddr[20:12]} :
207	                    (level == 2'd1) ?
208	                    {pte[53:28], pte[27:19], vaddr[20:12]} :
209	                    (((pte & `SV39_PTE_N) != {`XLEN{1'b0}}) ?
210	                     {pte[53:14], vaddr[15:12]} :
211	                     pte[53:10]),
212	                    vaddr[11:0]};
213	    end
214	  endfunction
215	
216	  function [`XLEN-1:0] merge_cross_page_packet;
217	    input [`XLEN-1:0] first_beat;
218	    input [`XLEN-1:0] second_beat;
219	    input [2:0] first_bytes;
220	    begin
221	      case (first_bytes)
222	        3'd1: merge_cross_page_packet = {second_beat[55:0], first_beat[7:0]};
223	        3'd2: merge_cross_page_packet = {second_beat[47:0], first_beat[15:0]};
224	        3'd3: merge_cross_page_packet = {second_beat[39:0], first_beat[23:0]};
225	        3'd4: merge_cross_page_packet = {second_beat[31:0], first_beat[31:0]};
226	        3'd5: merge_cross_page_packet = {second_beat[23:0], first_beat[39:0]};
227	        3'd6: merge_cross_page_packet = {second_beat[15:0], first_beat[47:0]};
228	        3'd7: merge_cross_page_packet = {second_beat[7:0], first_beat[55:0]};
229	        default: merge_cross_page_packet = first_beat;
230	      endcase
231	    end
232	  endfunction
233	
234	  wire req_paging_w = sv39_enabled(priv_mode_i, satp_i);
235	  wire [`XLEN-1:0] req_packet_end_pc_w = fetch_req_pc_i + 64'd7;
236	  wire [`XLEN-1:0] req_second_page_vaddr_w =
237	      {fetch_req_pc_i[`XLEN-1:12], 12'b0} + 64'd4096;
238	  wire [12:0] req_first_page_bytes_full_w =
239	      13'd4096 - {1'b0, fetch_req_pc_i[11:0]};
240	  wire req_same_fetch_page_w =
241	      fetch_req_pc_i[`XLEN-1:12] == req_packet_end_pc_w[`XLEN-1:12];
242	  wire req_cross_fetch_page_w = !req_same_fetch_page_w;
243	  wire [2:0] req_first_page_bytes_w =
244	      req_first_page_bytes_full_w[2:0];
245	  wire cache_hit_raw_w;
246	  wire pmp_active_w = (pmpcfg_i != {`PMP_CFG_BUS_W{1'b0}});
247	  // 声明前置，iverilog 14 拒绝前向引用（下方 cache_hit_w 提前引用这三个信号）
248	  wire req_itlb_hit_w;
249	  wire req_exec_pmp_fault_w;
250	  wire req_exec1_pmp_fault_w;
251	  // 为什么这么改：原实现只要 PMP 有任何活动条目就整体禁用取指包 cache
252	  // (cache_hit && !pmp_active)，导致真实 Linux/OpenSBI(总会配 PMP)下每次取指都
253	  // miss、退到慢速 AXI 取指，CPI 近乎翻倍。其实 PMP 权限本就每拍按当前 pmpcfg
254	  // 独立计算(req_exec_pmp_fault_w)；安全做法是命中时仍要求 PMP 放行，而不是禁用
255	  // 整个 cache。这样 PMP 会 fault 时 cache_hit=0 落到下方 fault 分支(语义不变)，
256	  // PMP 放行(Linux 下 DRAM 整片 RWX 的常态)时命中生效、恢复性能。
257	  // 非 PMP 场景(pmp_active=0)走 1'b1 分支，行为与原实现逐位一致。
258	  // SRAM 化后本式仅在 S_LOOKUP(判决拍)有意义：cache_hit_raw_w 是 SRAM 同步读结果，
259	  // ITLB/PMP 复检全部用 fire 拍锁存的请求上下文(paging_q/pc_q/req_priv_q/req_satp_q)。
260	  wire cache_hit_w = cache_hit_raw_w &&
261	      (pmp_active_w ? (!req_exec_pmp_fault_w && !req_exec1_pmp_fault_w &&
262	                       (!paging_q || req_itlb_hit_w))
263	                    : 1'b1);
264	  wire fetch_cache_context_unused_w;
265	  wire [`INST_W-1:0] cache_inst0_w;
266	  wire [`INST_W-1:0] cache_inst1_w;
267	  wire [1:0] cache_resp0_w;
268	  wire [1:0] cache_resp1_w;
269	  wire req_itlb_context_hit_w;
270	  wire [`XLEN-1:0] req_itlb_pte_w;
271	  wire [1:0] req_itlb_level_w;
272	  wire [`XLEN-1:0] req_itlb_paddr_w;
273	  // 判决拍(S_LOOKUP)复检链全部改用 fire 拍锁存值: svpbmt/priv/paging/pc 取
274	  // req_svpbmt_en_q/req_priv_q/paging_q/pc_q, 与 cache 内部锁存的请求同参照系。
275	  // pmpcfg/pmpaddr 仍取当拍输入(CSR 写经串行化, 无在飞取指请求交叠)。
276	  wire req_itlb_perm_fault_w =
277	      req_itlb_context_hit_w &&
278	      (pte_reserved_fault(req_itlb_pte_w, req_svpbmt_en_q, req_itlb_level_w) ||
279	       exec_permission_fault(req_itlb_pte_w, req_priv_q));
280	  assign req_itlb_hit_w = req_itlb_context_hit_w && !req_itlb_perm_fault_w;
281	  wire [`XLEN-1:0] req_exec_paddr_w =
282	      (paging_q && req_itlb_hit_w) ? req_itlb_paddr_w : pc_q;
283	  wire [`XLEN-1:0] req_exec1_paddr_w = req_exec_paddr_w + 64'd4;
284	  wire req_exec_pmp_fault_raw_w;
285	  wire req_exec1_pmp_fault_raw_w;
286	  assign req_exec_pmp_fault_w =
287	      (!paging_q || req_itlb_hit_w) && req_exec_pmp_fault_raw_w;
288	  assign req_exec1_pmp_fault_w =
289	      (!paging_q || req_itlb_hit_w) && req_exec1_pmp_fault_raw_w;
290	  wire fetch_req_fire_w = fetch_req_valid_i && fetch_req_ready_o;
291	  // direct miss 的 AR 从 fire 拍移到 S_LOOKUP 判决拍(同步读 +1 拍)。
292	  wire lookup_direct_miss_w =
293	      (state_q == S_LOOKUP) && !paging_q && !req_exec_pmp_fault_w &&
294	      !cache_hit_w;
295	  wire [`XLEN-1:0] pc_packet_end_w = pc_q + 64'd7;
296	  wire [`XLEN-1:0] pc_second_page_vaddr_w =
297	      {pc_q[`XLEN-1:12], 12'b0} + 64'd4096;
298	  wire [`XLEN-1:0] walk_vaddr_w =
299	      walk_second_q ? pc_second_page_vaddr_w : pc_q;
300	  wire [`XLEN-1:0] walk_pte_addr_w =
301	      pte_addr(walk_ppn_q, walk_vaddr_w, walk_level_q);
302	  wire [`XLEN-1:0] walk_leaf_exec_paddr_w =
303	      leaf_paddr(ifu_axi_rdata_i, walk_vaddr_w, walk_level_q);
304	  wire [`XLEN-1:0] walk_leaf_exec1_paddr_w =
305	      walk_leaf_exec_paddr_w + 64'd4;
306	  wire walk_leaf_exec_pmp_fault_w;
307	  wire walk_leaf_exec1_pmp_fault_w;
308	  wire [`XLEN-1:0] fetch0_addr_w = paging_q ? paddr0_q : pc_q;
309	  wire same_fetch_page_w =
310	      pc_q[`XLEN-1:12] == pc_packet_end_w[`XLEN-1:12];
311	  wire [`INST_W-1:0] fetch_beat_inst0_w = ifu_axi_rdata_i[`INST_W-1:0];
312	  wire [`INST_W-1:0] fetch_beat_inst1_w = ifu_axi_rdata_i[`XLEN-1:`INST_W];
313	  wire [`XLEN-1:0] merged_cross_packet_w =
314	      merge_cross_page_packet(first_beat_q, ifu_axi_rdata_i,
315	                              packet_first_bytes_q);
316	  wire first_inst_cross_page_w =
317	      packet_cross_page_q && (packet_first_bytes_q < 3'd4);
318	  wire itlb_fill_valid_w =
319	      !mmu_flush_i && (state_q == S_WALK_R) && ifu_axi_rvalid_i &&
320	      (ifu_axi_rresp_i == RESP_OK) &&
321	      !pte_invalid(ifu_axi_rdata_i) &&
322	      !pte_reserved_fault(ifu_axi_rdata_i, req_svpbmt_en_q, walk_level_q) &&
323	      (pte_leaf(ifu_axi_rdata_i)) &&
324	      !superpage_misaligned(ifu_axi_rdata_i, walk_level_q) &&
325	      !exec_permission_fault(ifu_axi_rdata_i, req_priv_q) &&
326	      // HW A: 首遍读到 A=0 的 PTE 不填 TLB(否则缓存 A=0 项); 待 S_AD_UPDATE 写完 re-walk
327	      // 读回 A=1 的 PTE 再填。TLB 因此永不缓存 A=0, TLB 命中路径无需 A 门控。
328	      !exec_ad_update_needed(ifu_axi_rdata_i);
329	  wire fetch_cache_fill_r0_w =
330	      (state_q == S_R0) && ifu_axi_rvalid_i &&
331	      (ifu_axi_rresp_i == RESP_OK) &&
332	      !packet_cross_page_q &&
333	      (resp0_q == RESP_OK) && (resp1_q == RESP_OK);
334	  // 不缓存跨页取指包:跨页包槽1 在下一物理页,而命中复检的 req_exec1_paddr_w=paddr0+4 是错页地址,
335	  // PMP 运行期 allow→deny 第二页且无取指 cache 失效时会绕过槽1 PMP(known-issues 隐患B)。
336	  // 跨页包改为每次重取(经 walk-leaf checker 用正确物理地址重查两页 PMP),结构性消除该隐患;
337	  // 交付不受影响(走 inst*_q 寄存器,与 fill 分离),跨页包稀少(PC 跨 4KB 边界),CPI 影响可忽略。
338	  wire fetch_cache_fill_r1_w =
339	      (state_q == S_R1) && ifu_axi_rvalid_i &&
340	      (ifu_axi_rresp_i == RESP_OK) &&
341	      !packet_cross_page_q &&
342	      (resp0_q == RESP_OK);
343	  // 填充恒开：缓存的是真实取回的指令字节，存入安全；是否供给由 cache_hit_w 的
344	  // PMP 放行门控决定。原来的 !pmp_active_w 门控会在 PMP 下让 cache 永不填充。
345	  wire fetch_cache_fill_valid_w =
346	      (fetch_cache_fill_r0_w || fetch_cache_fill_r1_w);
347	  wire [`INST_W-1:0] fetch_cache_fill_inst0_w =
348	      fetch_cache_fill_r1_w ? merged_cross_packet_w[`INST_W-1:0] :
349	                              fetch_beat_inst0_w;
350	  wire [`INST_W-1:0] fetch_cache_fill_inst1_w =
351	      fetch_cache_fill_r1_w ? merged_cross_packet_w[`XLEN-1:`INST_W] :
352	                              fetch_beat_inst1_w;
353	  wire [1:0] fetch_cache_fill_resp0_w =
354	      fetch_cache_fill_r1_w ? resp0_q : RESP_OK;
355	  wire [1:0] fetch_cache_fill_resp1_w = resp1_q;
356	
357	  // 两拍 lookup 协议: fire 拍(fetch_req_fire_w)发射 lookup_en 并传当拍请求上下文,
358	  // cache 内部锁存; 判决拍(S_LOOKUP)输出 cache_hit_raw_w/inst/resp 针对锁存请求有效。
359	  OooFetchPacketCache u_fetch_packet_cache (
360	    .clk(clk),
361	    .rst(rst),
362	    .clear_i(mmu_flush_i),
363	    .lookup_en_i(fetch_req_fire_w),
364	    .lookup_paging_i(req_paging_w),
365	    .lookup_priv_i(priv_mode_i),
366	    .lookup_satp_i(satp_i),
367	    .lookup_pc_i(fetch_req_pc_i),
368	    .lookup_context_hit_o(fetch_cache_context_unused_w),
369	    .lookup_hit_o(cache_hit_raw_w),
370	    .lookup_inst0_o(cache_inst0_w),
371	    .lookup_resp0_o(cache_resp0_w),
372	    .lookup_inst1_o(cache_inst1_w),
373	    .lookup_resp1_o(cache_resp1_w),
374	    .fill_valid_i(fetch_cache_fill_valid_w),
375	    .fill_paging_i(paging_q),
376	    .fill_priv_i(req_priv_q),
377	    .fill_satp_i(req_satp_q),
378	    .fill_pc_i(pc_q),
379	    .fill_inst0_i(fetch_cache_fill_inst0_w),
