806	              first_beat_q <= {`XLEN{1'b0}};
807	              inst0_q <= {`INST_W{1'b0}};
808	              inst1_q <= {`INST_W{1'b0}};
809	              resp0_q <= RESP_OK;
810	              resp1_q <= RESP_OK;
811	              paging_q <= req_paging_w;
812	              req_priv_q <= priv_mode_i;
813	              req_satp_q <= satp_i;
814	              req_svpbmt_en_q <= svpbmt_en_i;
815	              state_q <= S_LOOKUP;
816	            end else begin
817	              state_q <= S_IDLE;
818	            end
819	          end
820	        end
821	
822	        default: begin
823	          state_q <= S_IDLE;
824	        end
825	      endcase
826	    end
827	  end
828	
829	endmodule
